// =====================================================================
// FONTE ÚNICA DE VERDADE DO FLUXO
// ---------------------------------------------------------------------
// O bug do "-1 caso" nasceu de dois nós enxergando escopos diferentes:
//   Definir Pastas de Teste1 -> tests/parte1, tests/parte2, tests_performance
//   Extrair Arquivos Alterados1 -> /tests/, /tests_performance/
// Qualquer .robot em /tests/ fora de parte1|parte2 entrava na contagem de
// NOVOS casos e NÃO entrava no TOTAL GERAL.
// A partir daqui, pasta nova se resolve SÓ neste nó.
// =====================================================================
return [
  {
    json: {
      raizes_teste: ['tests', 'tests_performance'],
      prefixo_caso: 'GTPDV-T',
      extensao: '.robot',
      branch: 'develop',
      dias_atras: 21,
      top_commits: 1000,
      top_alteracoes: 2000
    }
  }
];

// Sentinela: mantém o ramo vivo até o Merge quando o período não produziu
// nada (sem commits, só merges, nenhum .robot tocado ou nenhum caso novo).
// Sem isso o Merge nunca recebia input 0 e o e-mail simplesmente não saía.
return [
  {
    json: {
      tipo_mudanca: 'nenhum',
      codigo: null,
      descricao: null,
      caminho_arquivo: null,
      regressao: [],
      tags: []
    }
  }
];

const cfg = $('Configuração Global').first().json;

// Escopo é a RAIZ, não a subpasta. O nó seguinte usa recursionLevel=Full,
// então desce sozinho em parte1/parte2/parteN e também pega arquivos
// soltos direto na raiz de /tests.
return (cfg.raizes_teste || []).map((pasta) => ({ json: { pasta } }));

const cfg = $('Configuração Global').first().json;
const extensao = String(cfg.extensao || '.robot').toLowerCase();

// O nó anterior roda uma vez para CADA raiz configurada em
// "Configuração Global", então combinamos o resultado de todas.
const arquivosRobot = [];
const vistos = new Set();

for (const entrada of $input.all()) {
  const itens = entrada.json.value || [];

  for (const item of itens) {
    if (item.gitObjectType !== 'blob') {
      continue;
    }

    const caminho = String(item.path || '');

    if (!caminho.toLowerCase().endsWith(extensao)) {
      continue;
    }

    // Blindagem contra escopos sobrepostos (ex.: /tests e /tests/parte1
    // configurados ao mesmo tempo) que inflariam o total geral.
    if (vistos.has(caminho)) {
      continue;
    }

    vistos.add(caminho);

    arquivosRobot.push({ json: { caminho_arquivo: caminho } });
  }
}

return arquivosRobot;

// =====================================================================
// CONTAGEM TOTAL DO PROJETO + DETECÇÃO DE DUPLICADOS + AUDITORIA
// ---------------------------------------------------------------------
// Mudanças em relação à versão anterior:
//  1. Arquivo sem "content" NÃO conta mais como zero silencioso -> vira
//     pendência explícita em auditoria.arquivos_sem_conteudo.
//  2. Guarda arquivo + LINHA de cada ocorrência -> duplicados rastreáveis.
//  3. Concilia com a busca "@GTPDV-T" do VS Code, apontando exatamente
//     quais linhas explicam a divergência.
//  4. NOVO: para cada código, reprocessa o bloco do caso usando o
//     CONTEÚDO ATUAL do arquivo (não o snapshot do diff) e extrai de
//     novo funcionalidade/criticidade/regressão/tags. Vira
//     "enriquecimento_atual", fonte de verdade usada em "Preparar
//     Dados para Relatório" para sobrescrever os campos derivados de
//     tags que "Enriquecer Caso de Teste" calculou em cima do commit
//     antigo (podendo estar desatualizados se a formatação das tags
//     foi corrigida em commit posterior dentro do mesmo período).
// =====================================================================
const cfg = $('Configuração Global').first().json;
const PREFIXO = cfg.prefixo_caso || 'GTPDV-T';

// DEFINIÇÃO: linha iniciando na coluna 0 com o código (com ou sem "@").
const reDefinicao = new RegExp('^@?(' + PREFIXO + '\\d+)\\b', 'i');

// MARCADOR: "@GTPDV-Tnnn" em qualquer posição = busca literal do VS Code.
const reMarcador = new RegExp('@' + PREFIXO + '\\d+', 'gi');

// Próximo caso / próxima seção -> delimitam o BLOCO de um caso, igual à
// lógica usada em "Enriquecer Caso de Teste" (mesma regra, aplicada aqui
// ao conteúdo atual em vez de ao conteúdo de referência do diff).
const reProximoCaso = new RegExp('^@?' + PREFIXO + '\\d+\\b', 'i');

function extrairBlocoCaso(linhas, indiceInicio) {
  let indiceFim = linhas.length;

  for (let i = indiceInicio + 1; i < linhas.length; i++) {
    const linha = linhas[i];

    const ehProximoCaso = reProximoCaso.test(linha);
    const ehNovaSecao = /^\*{3}\s*.+?\s*\*{3}\s*$/.test(linha);

    if (ehProximoCaso || ehNovaSecao) {
      indiceFim = i;
      break;
    }
  }

  return linhas.slice(indiceInicio, indiceFim).join('\n');
}

// Mesma extração de "Enriquecer Caso de Teste" (funcionalidade,
// criticidade, regressão, tags e o diagnóstico de "[Tags] mal
// formatada"), reaproveitada aqui 1:1 para rodar sobre o BLOCO ATUAL
// em vez do bloco histórico do diff. Mantém os dois pontos do fluxo
// consistentes: a mesma regra classifica o mesmo jeito nos dois lugares.
const CRITICIDADES_PERMITIDAS = [
  'critico', 'crítico',
  'alto', 'alta',
  'medio', 'médio',
  'media', 'média',
  'baixo', 'baixa'
];

const REGRESSOES_PERMITIDAS = ['regressivo-completo', 'mini-regressivo'];

// =====================================================================
// NOVO: extração de bug via [Documentation]. Padrão no repositório:
//   [Documentation]    [Bug]     DVAROMNIP-1234:  Título da issue
// Pode vir com continuação Robot Framework ("..." na(s) linha(s)
// seguinte(s)) quando a documentação é multi-linha. Regra confirmada
// com o QA: no máximo 1 bug por caso de teste.
// =====================================================================
const RE_BUG = /\[Bug\]\s+DVAROMNIP-(\d+):\s*(.+)/i;

function extrairInfoBug(bloco) {
  const linhasBloco = bloco.split(/\r?\n/);
  const indiceDoc = linhasBloco.findIndex((linha) => /^\s*\[Documentation\]/i.test(linha));

  if (indiceDoc === -1) {
    return null;
  }

  const partesDoc = [linhasBloco[indiceDoc].replace(/^\s*\[Documentation\]\s*/i, '')];

  for (let i = indiceDoc + 1; i < linhasBloco.length; i++) {
    const continuacao = linhasBloco[i].match(/^\s*\.\.\.\s?(.*)$/);

    if (!continuacao) {
      break;
    }

    partesDoc.push(continuacao[1]);
  }

  const documentacao = partesDoc.join('\n');
  const bugMatch = documentacao.match(RE_BUG);

  if (!bugMatch) {
    return null;
  }

  return {
    issue: 'DVAROMNIP-' + bugMatch[1],
    numero_issue: bugMatch[1],
    titulo_issue: bugMatch[2].trim()
  };
}

function extrairInfoTags(bloco, prefixo) {
  const tagsMatch = bloco.match(/^\s*\[Tags\]\s+(.*)$/mi);
  const linhaTagsBruta = tagsMatch ? String(tagsMatch[1]).trim() : '';

  const tags = tagsMatch
    ? linhaTagsBruta
        .split(/\s{2,}|\t+|\s+(?=[^\s]+$)/)
        .map((tag) => tag.trim())
        .filter(Boolean)
    : [];

  const tagsNormalizadas = tags.map((tag) => tag.toLowerCase());

  const indiceFuncionalidade = tags.findIndex((tag, index) => {
    const normalizada = tagsNormalizadas[index];

    return (
      !new RegExp('^' + prefixo.split('-')[0] + '-', 'i').test(tag) &&
      !CRITICIDADES_PERMITIDAS.includes(normalizada) &&
      !REGRESSOES_PERMITIDAS.includes(normalizada)
    );
  });

  const indiceCriticidade = tagsNormalizadas.findIndex(
    (tag) => CRITICIDADES_PERMITIDAS.includes(tag)
  );

  const funcionalidade = indiceFuncionalidade >= 0 ? tags[indiceFuncionalidade] : null;
  const criticidade = indiceCriticidade >= 0 ? tags[indiceCriticidade] : null;

  const regressao = tags.filter((tag, index) =>
    REGRESSOES_PERMITIDAS.includes(tagsNormalizadas[index])
  );

  const tagsMalFormatadas =
    tags.length > 0 &&
    (
      tags.some((tag) => /\s/.test(tag) && tag.split(/\s+/).length > 1) ||
      criticidade === null
    );

  return {
    tags,
    linha_tags_bruta: linhaTagsBruta,
    funcionalidade,
    criticidade,
    regressao,
    tags_mal_formatadas: tagsMalFormatadas
  };
}

const entradas = $input.all();
const listagem = $('Filtrar Arquivos Robot').all();

const porArquivo = [];
const ocorrencias = new Map();
const arquivosSemConteudo = [];
const caminhosRepetidos = [];
const definicoesSemArroba = [];
const marcadoresForaDeDefinicao = [];
const vistos = new Set();

// codigo -> { funcionalidade, criticidade, regressao, tags,
// linha_tags_bruta, tags_mal_formatadas } calculado sobre o BLOCO ATUAL.
// Se o código tiver mais de uma ocorrência (duplicado), fica a versão
// não-malformada quando existir uma, para não penalizar o relatório por
// causa de uma cópia órfã desatualizada.
const enriquecimentoAtualPorCodigo = new Map();

// codigo -> { issue, numero_issue, titulo_issue, caminho_arquivo, linha }
// para casos de teste cujo [Documentation] referencia um bug aberto.
const casosComBugPorCodigo = new Map();

let totalDefinicoes = 0;
let totalMarcadores = 0;

for (let i = 0; i < entradas.length; i++) {
  const json = entradas[i].json || {};

  const caminho =
    json.path ||
    json.caminho_arquivo ||
    listagem[i]?.json?.caminho_arquivo ||
    null;

  if (!caminho) {
    arquivosSemConteudo.push({
      caminho: 'desconhecido (índice ' + i + ')',
      motivo: 'Resposta sem path e sem correspondência na listagem.'
    });
    continue;
  }

  if (vistos.has(caminho)) {
    caminhosRepetidos.push(caminho);
    continue;
  }

  vistos.add(caminho);

  const bruto = typeof json.content === 'string' ? json.content : null;

  if (bruto === null || bruto.length === 0) {
    arquivosSemConteudo.push({
      caminho,
      motivo:
        'A API não retornou "content" como string (erro HTTP, conteúdo binário ou arquivo grande demais).'
    });
    continue;
  }

  const conteudo = bruto.replace(/^\uFEFF/, '');
  const linhas = conteudo.split(/\r\n|\r|\n/);

  const partes = caminho.split('/').filter(Boolean);
  const nomeArquivo = partes[partes.length - 1] || caminho;
  const pasta = partes.slice(0, -1).join('/') || '/';
  const raiz = partes[0] || '/';

  let definicoesArquivo = 0;
  let marcadoresArquivo = 0;

  for (let l = 0; l < linhas.length; l++) {
    const linha = linhas[l];

    const marcadores = linha.match(reMarcador) || [];
    totalMarcadores += marcadores.length;
    marcadoresArquivo += marcadores.length;

    const m = linha.match(reDefinicao);

    if (m) {
      const codigo = String(m[1]).toUpperCase();

      definicoesArquivo++;
      totalDefinicoes++;

      if (!ocorrencias.has(codigo)) {
        ocorrencias.set(codigo, []);
      }

      ocorrencias.get(codigo).push({
        caminho,
        arquivo: nomeArquivo,
        linha: l + 1,
        texto: linha.trim().slice(0, 160)
      });

      const blocoAtual = extrairBlocoCaso(linhas, l);
      const infoAtual = extrairInfoTags(blocoAtual, PREFIXO);
      const infoBug = extrairInfoBug(blocoAtual);

      if (infoBug && !casosComBugPorCodigo.has(codigo)) {
        casosComBugPorCodigo.set(codigo, {
          codigo,
          issue: infoBug.issue,
          titulo_issue: infoBug.titulo_issue,
          caminho_arquivo: caminho,
          linha: l + 1
        });
      }

      const existente = enriquecimentoAtualPorCodigo.get(codigo);

      if (!existente || (existente.tags_mal_formatadas && !infoAtual.tags_mal_formatadas)) {
        enriquecimentoAtualPorCodigo.set(codigo, infoAtual);
      }

      if (!linha.startsWith('@')) {
        // Conta aqui, NÃO conta na busca "@GTPDV-T" do VS Code.
        definicoesSemArroba.push({
          caminho,
          linha: l + 1,
          texto: linha.trim().slice(0, 160)
        });
      }
    }

    // Marcadores que o VS Code conta mas que não são definição de caso
    // (comentário, [Documentation], tag inline, etc.) OU que SÃO uma
    // definição de caso de verdade, só que perdida porque a linha tem
    // espaço/tab antes do "@" (Robot Framework exige nome de Test Case
    // começando na coluna 0 — com indentação, vira "step" do caso
    // anterior, não um novo caso).
    const extras =
      m && linha.startsWith('@') ? marcadores.length - 1 : marcadores.length;

    if (extras > 0) {
      const possivelDefinicaoPerdida =
        !linha.startsWith('@') && reDefinicao.test(linha.trim());

      marcadoresForaDeDefinicao.push({
        caminho,
        linha: l + 1,
        quantidade: extras,
        texto: linha.trim().slice(0, 160),
        possivel_definicao_perdida: possivelDefinicaoPerdida
      });
    }
  }

  // total_marcadores_arroba = o que uma busca literal por "@GTPDV-T" no
  // editor deve retornar PARA ESTE ARQUIVO. Se vier diferente de
  // "quantidade", esse é o arquivo com divergência - sem precisar cruzar
  // manualmente os 30 arquivos com a auditoria global.
  porArquivo.push({
    arquivo: nomeArquivo,
    pasta,
    raiz,
    caminho,
    quantidade: definicoesArquivo,
    total_marcadores_arroba: marcadoresArquivo,
    divergencia: marcadoresArquivo - definicoesArquivo
  });
}

porArquivo.sort((a, b) =>
  a.pasta !== b.pasta
    ? a.pasta.localeCompare(b.pasta)
    : a.arquivo.localeCompare(b.arquivo, 'pt-BR', { numeric: true })
);

const mapaPasta = {};

for (const linha of porArquivo) {
  mapaPasta[linha.raiz] = (mapaPasta[linha.raiz] || 0) + linha.quantidade;
}

const totalPorPasta = Object.entries(mapaPasta)
  .map(([pasta, quantidade]) => ({ pasta, quantidade }))
  .sort((a, b) => a.pasta.localeCompare(b.pasta));

// ===== REQUISITO 3: DUPLICADOS =====
const codigosDuplicados = [];

for (const [codigo, lista] of ocorrencias) {
  if (lista.length <= 1) {
    continue;
  }

  const arquivosDistintos = new Set(lista.map((o) => o.caminho));

  codigosDuplicados.push({
    codigo,
    quantidade: lista.length,
    tipo:
      arquivosDistintos.size > 1
        ? 'Entre arquivos diferentes'
        : 'Repetido no mesmo arquivo',
    ocorrencias: lista.map((o) => ({
      arquivo: o.arquivo,
      caminho: o.caminho,
      linha: o.linha,
      texto: o.texto
    }))
  });
}

codigosDuplicados.sort(
  (a, b) =>
    b.quantidade - a.quantidade ||
    a.codigo.localeCompare(b.codigo, 'pt-BR', { numeric: true })
);

const totalDuplicados = totalDefinicoes - ocorrencias.size;

// ===== NOVO: REGRA DE OBRIGATORIEDADE DE TAGS =====
// Política: todo caso de teste precisa ter a tag "regressivo-completo"
// (mesmo que também tenha "mini-regressivo") e uma tag de criticidade
// (baixo/medio/alto/critico). Roda sobre TODO o projeto (não só os
// casos novos do período), reaproveitando o que "enriquecimento_atual"
// já calculou por código - nenhuma nova varredura de arquivo.
const codigosSemRegressivoCompleto = [];
const codigosSemCriticidade = [];

for (const [codigo, info] of enriquecimentoAtualPorCodigo) {
  const primeiraOcorrencia = (ocorrencias.get(codigo) || [])[0] || {};

  const temRegressivoCompleto = (info.regressao || []).some(
    (tag) => String(tag).toLowerCase() === 'regressivo-completo'
  );

  if (!temRegressivoCompleto) {
    codigosSemRegressivoCompleto.push({
      codigo,
      caminho_arquivo: primeiraOcorrencia.caminho || null,
      linha: primeiraOcorrencia.linha || null,
      linha_tags_bruta: info.linha_tags_bruta
    });
  }

  if (!info.criticidade) {
    codigosSemCriticidade.push({
      codigo,
      caminho_arquivo: primeiraOcorrencia.caminho || null,
      linha: primeiraOcorrencia.linha || null,
      linha_tags_bruta: info.linha_tags_bruta
    });
  }
}

const ordenarPorCodigo = (a, b) =>
  a.codigo.localeCompare(b.codigo, 'pt-BR', { numeric: true });

codigosSemRegressivoCompleto.sort(ordenarPorCodigo);
codigosSemCriticidade.sort(ordenarPorCodigo);

// ===== CONCILIAÇÃO COM A BUSCA DO VS CODE =====
const extrasTotal = marcadoresForaDeDefinicao.reduce(
  (soma, x) => soma + x.quantidade,
  0
);

const auditoria = {
  arquivos_lidos: porArquivo.length,
  total_marcadores_arroba: totalMarcadores,
  conferencia: {
    definicoes: totalDefinicoes,
    menos_definicoes_sem_arroba: definicoesSemArroba.length,
    mais_marcadores_fora_de_definicao: extrasTotal,
    resultado_esperado_vscode:
      totalDefinicoes - definicoesSemArroba.length + extrasTotal
  },
  definicoes_sem_arroba: definicoesSemArroba,
  marcadores_fora_de_definicao: marcadoresForaDeDefinicao,
  arquivos_sem_conteudo: arquivosSemConteudo,
  caminhos_repetidos: caminhosRepetidos
};

return [
  {
    json: {
      total_geral: totalDefinicoes,
      total_codigos_unicos: ocorrencias.size,
      total_duplicados: totalDuplicados,
      por_suite: porArquivo,
      total_por_pasta: totalPorPasta,
      codigos_duplicados: codigosDuplicados,
      // Snapshot fiel de "o que existe HOJE no projeto" (varredura direta
      // do branch, não reconstrução por histórico de commits). É a fonte
      // de verdade usada para validar novo/removido calculados por diff.
      codigos_atuais: Array.from(ocorrencias.keys()),
      // NOVO: snapshot fiel de funcionalidade/criticidade/regressão/tags
      // "HOJE" no branch, por código. Fonte de verdade usada em "Preparar
      // Dados para Relatório" para sobrescrever os campos que
      // "Enriquecer Caso de Teste" calculou em cima do conteúdo do commit
      // em que o caso foi detectado (que pode já estar desatualizado se a
      // formatação das tags foi corrigida em commit posterior, dentro do
      // mesmo período analisado).
      enriquecimento_atual: Object.fromEntries(enriquecimentoAtualPorCodigo),
      // NOVO: casos do projeto INTEIRO com bug aberto referenciado no
      // [Documentation] (padrão "[Bug]     DVAROMNIP-<numero>:  titulo").
      // Mesmo corte de exibição (LIMITE_EXEMPLOS_REGRAS_TAGS) aplicado em
      // "Preparar Dados para Relatório", igual às demais auditorias de
      // projeto inteiro.
      casos_com_bug: Array.from(casosComBugPorCodigo.values()).sort(
        (a, b) => a.codigo.localeCompare(b.codigo, 'pt-BR', { numeric: true })
      ),
      // NOVO: casos do projeto INTEIRO (não só os novos do período) que
      // não atendem a política obrigatória de tags. Ordenados; a
      // paginação/corte para exibição fica a cargo de "Preparar Dados
      // para Relatório", que decide quantos exemplos cabem no e-mail.
      regras_de_tags: {
        sem_regressivo_completo: codigosSemRegressivoCompleto,
        sem_criticidade: codigosSemCriticidade,
        total_sem_regressivo_completo: codigosSemRegressivoCompleto.length,
        total_sem_criticidade: codigosSemCriticidade.length
      },
      auditoria
    }
  }
];

const cfg = $('Configuração Global').first().json;

const diasAtras = cfg.dias_atras || 7;

// Janela FECHADA. A versão anterior usava fim = "agora", então cada execução
// semanal sobrepunha a anterior nas horas já decorridas do dia e o mesmo
// commit podia ser contado como "novo" em dois relatórios seguidos.
const dataFim = new Date();
dataFim.setHours(0, 0, 0, 0);

const dataInicio = new Date(dataFim);
dataInicio.setDate(dataInicio.getDate() - diasAtras);

return [
  {
    json: {
      dias_atras: diasAtras,
      data_inicio: dataInicio.toISOString(),
      data_fim: dataFim.toISOString(),
      descricao_periodo: `${diasAtras} dias fechados até 00:00 de hoje`
    }
  }
];

const cfg = $('Configuração Global').first().json;
const limite = cfg.top_commits || 1000;

const resposta = $input.first().json;
const commits = resposta.value || [];

// A API do Azure DevOps trunca em $top SEM avisar. Se bater no limite,
// o relatório precisa dizer que o período pode estar incompleto.
const truncado = commits.length >= limite;

return commits.map((commit) => ({
  json: {
    commitId: commit.commitId,
    comment: commit.comment,
    autor: commit.author?.name || null,
    data_commit: commit.committer?.date || null,
    commits_truncados: truncado
  }
}));

return $input.all().filter((item) => {
  const comentario = String(item.json.comment || '').trim();

  // Item sentinela (nenhum commit no período) passa direto para o IF decidir.
  if (!item.json.commitId) {
    return true;
  }

  const ehMerge =
    /^merged?\s+pr\b/i.test(comentario) ||
    /^merge\s+(pull request|branch)\b/i.test(comentario);

  return !ehMerge;
});

const cfg = $('Configuração Global').first().json;

const limiteAlteracoes = cfg.top_alteracoes || 2000;
const pastasPermitidas = (cfg.raizes_teste || []).map((p) => '/' + p + '/');
const extensao = String(cfg.extensao || '.robot').toLowerCase();

const itens = $input.all();
const arquivos = [];

for (const item of itens) {
  const dados = item.json;
  const alteracoes = dados.changes || [];

  // /commits/{id}/changes também trunca em $top sem sinalizar.
  const truncado = alteracoes.length >= limiteAlteracoes;

  for (const alteracao of alteracoes) {
    const arquivo = alteracao.item;

    if (!arquivo) {
      continue;
    }

    const caminho = String(arquivo.path || '');
    const caminhoLower = caminho.toLowerCase();

    const tipoArquivo = String(arquivo.gitObjectType || '').toLowerCase();

    // A API do Azure DevOps concatena flags de changeType (ex.: "rename, edit"
    // quando o arquivo foi renomeado E editado no mesmo commit). Comparação
    // com === nunca bate nesses casos -> a alteração era descartada em
    // silêncio. Trocado por checagem de substring.
    const tipoAlteracao = String(alteracao.changeType || '').toLowerCase();

    const ehRename = tipoAlteracao.includes('rename');
    const ehDelete = tipoAlteracao.includes('delete');
    const ehEditOuAdd =
      (tipoAlteracao.includes('edit') || tipoAlteracao.includes('add')) &&
      tipoArquivo === 'blob';

    const estaEmPastaPermitida = pastasPermitidas.some(
      (pasta) => caminhoLower.startsWith(pasta)
    );

    const ehRobot =
      estaEmPastaPermitida &&
      caminhoLower.endsWith(extensao);

    const ehAlteracaoValida = ehEditOuAdd || ehDelete || ehRename;

    if (!ehRobot || !ehAlteracaoValida) {
      continue;
    }

    // Em rename (ou rename+edit), o conteúdo ANTERIOR mora no path ANTIGO
    // (sourceServerItem), não no novo. Buscar o path novo no commit pai
    // sempre dá 404 -> conteudo_anterior vira '' -> TODOS os casos do
    // arquivo entram como "novo" por engano (era exatamente o bug relatado
    // de suíte renomeada inflando a contagem em períodos longos).
    const caminhoAnterior =
      ehRename && alteracao.sourceServerItem
        ? String(alteracao.sourceServerItem)
        : caminho;

    arquivos.push({
      json: {
        commitId: dados.commitId,
        caminho_arquivo: caminho,
        caminho_arquivo_anterior: caminhoAnterior,
        objectId_atual: arquivo.objectId || null,
        changeType: tipoAlteracao,
        data_commit: dados.data_commit,
        autor: dados.autor,
        comentario_commit: dados.comment,
        alteracoes_truncadas: truncado
      }
    });
  }
}

return arquivos;

const metadados = $('Extrair Commit Pai').all();
