function obterConteudo(item) {
  const json = item?.json || {};

  if (typeof json.content === 'string') {
    return json.content;
  }

  if (typeof json.body?.content === 'string') {
    return json.body.content;
  }

  if (typeof json.data?.content === 'string') {
    return json.data.content;
  }

  return '';
}

return metadados.map((item, index) => {
