      commitId_atual: meta.commitId_atual,
      commitId_anterior: meta.commitId_anterior,

      data_commit: meta.data_commit,
      autor: meta.autor,
      comentario_commit: meta.comentario_commit,

      conteudo_anterior: obterConteudo(anterior),
      conteudo_atual: obterConteudo(atual)
    }
  };
});

const cfg = $('Configuração Global').first().json;
const PREFIXO = cfg.prefixo_caso || 'GTPDV-T';

const itens = $input.all();

function extrairCasos(conteudo) {
  const mapa = new Map();

  if (typeof conteudo !== 'string' || !conteudo) {
    return mapa;
  }

  const regex = new RegExp(
    '^@?(' + PREFIXO + '\\d+)\\b[ \\t]*(?:-[ \\t]*)?(.*)$',
    'gmi'
  );

  for (const match of conteudo.matchAll(regex)) {
    const codigo = String(match[1] || '').toUpperCase();
    const descricao = String(match[2] || '').trim();

    if (!mapa.has(codigo)) {
      mapa.set(codigo, descricao);
    }
  }

  return mapa;
}

const eventosPorCodigo = new Map();

function adicionarEvento(codigo, evento) {
  if (!eventosPorCodigo.has(codigo)) {
    eventosPorCodigo.set(codigo, []);
  }

  eventosPorCodigo.get(codigo).push(evento);
}

for (const item of itens) {
  const dados = item.json;

  const casosAnteriores = extrairCasos(dados.conteudo_anterior || '');
  const casosAtuais = extrairCasos(dados.conteudo_atual || '');

  const metadados = {
    caminho_arquivo: dados.caminho_arquivo,
    changeType: dados.changeType,
    commitId_atual: dados.commitId_atual,
    commitId_anterior: dados.commitId_anterior,
    data_commit: dados.data_commit,
    autor: dados.autor,
    comentario_commit: dados.comentario_commit
  };

  for (const [codigo, descricao] of casosAtuais) {
    if (!casosAnteriores.has(codigo)) {
      adicionarEvento(codigo, {
        tipo_mudanca: 'novo',
        codigo,
        descricao,
        conteudo_referencia: dados.conteudo_atual || '',
        ...metadados
      });
    }
  }

  for (const [codigo, descricao] of casosAnteriores) {
    if (!casosAtuais.has(codigo)) {
      adicionarEvento(codigo, {
        tipo_mudanca: 'removido',
        codigo,
        descricao,
        conteudo_referencia: dados.conteudo_anterior || '',
        ...metadados
      });
    }
  }
}

const resultado = [];

for (const [codigo, eventosOriginais] of eventosPorCodigo) {
  /*
   * Quando o mesmo código é removido de um arquivo e adicionado em outro no
   * mesmo commit, trata-se de movimentação/renomeação e não de caso novo.
   */
  const eventosPorCommit = new Map();

  for (const evento of eventosOriginais) {
    const chave =
      evento.commitId_atual ||
      evento.data_commit ||
      'sem-commit';

    if (!eventosPorCommit.has(chave)) {
      eventosPorCommit.set(chave, []);
    }

    eventosPorCommit.get(chave).push(evento);
  }

  const eventos = [];

  for (const grupo of eventosPorCommit.values()) {
    const possuiNovo = grupo.some((evento) => evento.tipo_mudanca === 'novo');
    const possuiRemovido = grupo.some((evento) => evento.tipo_mudanca === 'removido');

    if (possuiNovo && possuiRemovido) {
      continue;
    }

    eventos.push(...grupo);
  }

  if (eventos.length === 0) {
    continue;
  }

  eventos.sort((a, b) => {
    const dataA = Date.parse(a.data_commit || '') || 0;
    const dataB = Date.parse(b.data_commit || '') || 0;

    return dataA - dataB;
  });

  const primeiro = eventos[0];

  const existiaNoInicio = primeiro.tipo_mudanca === 'removido';

  let existeNoFinal = existiaNoInicio;

  for (const evento of eventos) {
    existeNoFinal = evento.tipo_mudanca === 'novo';
  }

  if (existiaNoInicio === existeNoFinal) {
    continue;
  }

  if (!existiaNoInicio && existeNoFinal) {
    const eventoFinal = [...eventos]
      .reverse()
      .find((evento) => evento.tipo_mudanca === 'novo');

    resultado.push({ json: eventoFinal });

    continue;
  }

  const eventoFinal = [...eventos]
    .reverse()
    .find((evento) => evento.tipo_mudanca === 'removido');

  resultado.push({ json: eventoFinal });
}

resultado.sort((a, b) => {
  const dataA = Date.parse(a.json.data_commit || '') || 0;
  const dataB = Date.parse(b.json.data_commit || '') || 0;

  if (dataA !== dataB) {
    return dataA - dataB;
  }

  return String(a.json.codigo).localeCompare(
    String(b.json.codigo),
    'pt-BR',
    { numeric: true }
  );
});

// REQUISITO 2: período sem novidade ainda precisa gerar relatório.
if (resultado.length === 0) {
  return [
    {
      json: {
        tipo_mudanca: 'nenhum',
        codigo: null,
        descricao: null,
        caminho_arquivo: null,
        regressao: [],
        tags: []
      }
    }
  ];
}

return resultado;

const cfg = $('Configuração Global').first().json;
const PREFIXO = cfg.prefixo_caso || 'GTPDV-T';

const resultado = [];

function escaparRegex(valor) {
  const especiais = '\\^$.*+?()[]{}|';

  return String(valor)
    .split('')
    .map((caractere) => (especiais.includes(caractere) ? '\\' + caractere : caractere))
    .join('');
}

for (const item of $input.all()) {
  const dados = item.json;

  // Sentinela de "período sem novos casos" atravessa sem processamento.
  if (dados.tipo_mudanca === 'nenhum') {
    resultado.push({ json: dados });
    continue;
  }

  const codigo = String(dados.codigo || '');
  const conteudo = String(dados.conteudo_referencia || '');

  const linhas = conteudo.split(/\r?\n/);
  const regexCodigo = new RegExp('^@?' + escaparRegex(codigo) + '\\b', 'i');

  const indiceInicio = linhas.findIndex((linha) => regexCodigo.test(linha));

  if (indiceInicio === -1) {
    resultado.push({
      json: {
        ...dados,
        funcionalidade: null,
        criticidade: null,
        regressao: [],
        tags: [],
        bloco_teste: '',
        erro: 'Caso não encontrado no conteúdo de referência.'
      }
    });

    continue;
  }

  let indiceFim = linhas.length;

  const regexProximoCaso = new RegExp('^@?' + PREFIXO + '\\d+\\b', 'i');

  for (let i = indiceInicio + 1; i < linhas.length; i++) {
    const linha = linhas[i];

    const ehProximoCaso = regexProximoCaso.test(linha);
    const ehNovaSecao = /^\*{3}\s*.+?\s*\*{3}\s*$/.test(linha);

    if (ehProximoCaso || ehNovaSecao) {
      indiceFim = i;
      break;
    }
  }

  const bloco = linhas.slice(indiceInicio, indiceFim).join('\n');

  const tagsMatch = bloco.match(/^\s*\[Tags\]\s+(.*)$/mi);
  const linhaTagsBruta = tagsMatch ? String(tagsMatch[1]).trim() : '';

  const tags = tagsMatch
    ? linhaTagsBruta
        .split(/\s{2,}|\t+|\s+(?=[^\s]+$)/)
        .map((tag) => tag.trim())
        .filter(Boolean)
    : [];

  const tagsNormalizadas = tags.map((tag) => tag.toLowerCase());

  const criticidadesPermitidas = [
    'critico', 'crítico',
    'alto', 'alta',
    'medio', 'médio',
    'media', 'média',
    'baixo', 'baixa'
  ];

  const regressoesPermitidas = ['regressivo-completo', 'mini-regressivo'];

  const indiceFuncionalidade = tags.findIndex((tag, index) => {
    const normalizada = tagsNormalizadas[index];

    return (
      !new RegExp('^' + PREFIXO.split('-')[0] + '-', 'i').test(tag) &&
      !criticidadesPermitidas.includes(normalizada) &&
      !regressoesPermitidas.includes(normalizada)
    );
  });

  const indiceCriticidade = tagsNormalizadas.findIndex(
    (tag) => criticidadesPermitidas.includes(tag)
  );

  const funcionalidade = indiceFuncionalidade >= 0 ? tags[indiceFuncionalidade] : null;
  const criticidade = indiceCriticidade >= 0 ? tags[indiceCriticidade] : null;

  const regressao = tags.filter((tag, index) =>
    regressoesPermitidas.includes(tagsNormalizadas[index])
  );

  /*
   * DEFEITO DE REPOSITÓRIO, não do fluxo:
   * [Tags] separado por espaço SIMPLES vira UMA tag só. O próprio Robot
   * Framework interpreta igual, então esses testes não são selecionados por
   * --include medio / --include regressivo-completo. Sinalizamos no relatório.
   */
  const tagsMalFormatadas =
    tags.length > 0 &&
    (
      tags.some((tag) => /\s/.test(tag) && tag.split(/\s+/).length > 1) ||
      criticidade === null
    );

  resultado.push({
    json: {
      tipo_mudanca: dados.tipo_mudanca,
      codigo: dados.codigo,
      descricao: dados.descricao,
      caminho_arquivo: dados.caminho_arquivo,
      changeType: dados.changeType,
      commitId_atual: dados.commitId_atual,
      commitId_anterior: dados.commitId_anterior,
      data_commit: dados.data_commit,
      autor: dados.autor,
      comentario_commit: dados.comentario_commit,
      funcionalidade,
      criticidade,
      regressao,
      tags,
      linha_tags_bruta: linhaTagsBruta,
      tags_mal_formatadas: tagsMalFormatadas,
      bloco_teste: bloco
    }
  });
}

return resultado;

