// sobrescritos pelo estado ATUAL do arquivo (quando disponível). Os
// demais campos (bloco_teste, usa_*, complexidade, commitId, autor...)
// permanecem os originais do diff, pois não são afetados por esse defeito.
const casos = novosNoProjeto.map((c) => {
