    cliente: percentual(recursos.cliente, total),
    produto: percentual(recursos.produto, total),
    pagamento: percentual(recursos.pagamento, total),
    pre_venda: percentual(recursos.pre_venda, total),
    embalagem: percentual(recursos.embalagem, total),
    entrega: percentual(recursos.entrega, total)
  },

  recursos,
  casos,
  casos_removidos,
  por_suite: porSuite,
  total_por_pasta: totalPorPasta,
  codigos_duplicados: codigosDuplicados,
  casos_tags_mal_formatadas: casosTagsRuins.map((c) => ({
    codigo: c.codigo,
    caminho_arquivo: c.caminho_arquivo,
    linha_tags_bruta: c.linha_tags_bruta
  })),
  // NOVO: exemplos (limitados) de casos do projeto sem "regressivo-completo"
  // ou sem criticidade definida. Contagem total sempre real; lista exibida
  // é cortada em LIMITE_EXEMPLOS_REGRAS_TAGS para não inflar o e-mail.
  casos_sem_regressivo_completo: semRegressivoCompletoBruto.slice(0, LIMITE_EXEMPLOS_REGRAS_TAGS),
  casos_sem_regressivo_completo_total: semRegressivoCompletoBruto.length,
  casos_sem_criticidade: semCriticidadeBruto.slice(0, LIMITE_EXEMPLOS_REGRAS_TAGS),
  casos_sem_criticidade_total: semCriticidadeBruto.length,
  // NOVO: casos do projeto inteiro com bug aberto referenciado no
  // [Documentation] (issue DVAROMNIP). Mesmo corte de exibição das
  // demais auditorias de projeto inteiro.
  casos_com_bug: casosComBugBruto.slice(0, LIMITE_EXEMPLOS_REGRAS_TAGS),
  casos_com_bug_total: casosComBugBruto.length,
  auditoria
};

// ===== INSIGHTS =====
dashboard.insights = [];

dashboard.insights.push(
  `O projeto possui atualmente ${totalGeral} definições de casos de teste (${totalUnicos} códigos únicos).`
);

if (total === 0) {
  dashboard.insights.push(
    'Nenhum novo caso de teste automatizado foi criado neste repositório no período analisado.'
  );
} else {
  dashboard.insights.push(`${total} novo(s) caso(s) de teste criado(s) no período.`);
}

if (totalRemovidos > 0) {
  dashboard.insights.push(
    `${totalRemovidos} caso(s) deixaram de existir no repositório neste período. Avalie a retirada formal do plano de testes.`
  );
}

if (removidosFalsoPositivo.length > 0) {
  dashboard.insights.push(
    `${removidosFalsoPositivo.length} caso(s) identificados por commit como "removidos" na verdade continuam no projeto hoje (foram movidos/alterados, não excluídos) e não entraram na contagem de removidos.`
  );
}

if (totalDuplicados > 0) {
  dashboard.insights.push(
    `${totalDuplicados} definição(ões) duplicada(s) detectada(s), envolvendo ${codigosDuplicados.length} código(s). Duplicidade infla a cobertura reportada e causa execução redundante na pipeline.`
  );
} else {
  dashboard.insights.push('Nenhum código de caso de teste duplicado no repositório.');
}

if (casosTagsRuins.length > 0) {
  dashboard.insights.push(
    `${casosTagsRuins.length} caso(s) novo(s) com [Tags] mal formatadas (separador de espaço simples) que AINDA persistem no repositório hoje. O Robot Framework trata isso como UMA tag única, então esses testes não são selecionados por --include criticidade/regressão.`
  );
}

if (tagsCorrigidasNoPeriodo.length > 0) {
  dashboard.insights.push(
    `${tagsCorrigidasNoPeriodo.length} caso(s) tiveram [Tags] mal formatadas identificadas no período, mas já foram corrigidos e não aparecem mais na lista abaixo.`
  );
}

if (semRegressivoCompletoBruto.length > 0) {
  dashboard.insights.push(
    `Atenção: ${semRegressivoCompletoBruto.length} caso(s) no projeto sem a tag "regressivo-completo" — ficam de fora de qualquer execução --include regressivo-completo.` +
    (semRegressivoCompletoBruto.length > LIMITE_EXEMPLOS_REGRAS_TAGS
      ? ` Exibindo os primeiros ${LIMITE_EXEMPLOS_REGRAS_TAGS} na tabela abaixo.`
      : '')
  );
}

if (semCriticidadeBruto.length > 0) {
  dashboard.insights.push(
    `Atenção: ${semCriticidadeBruto.length} caso(s) no projeto sem nível de criticidade definido (baixo, médio, alto ou crítico) na linha [Tags].` +
    (semCriticidadeBruto.length > LIMITE_EXEMPLOS_REGRAS_TAGS
      ? ` Exibindo os primeiros ${LIMITE_EXEMPLOS_REGRAS_TAGS} na tabela abaixo.`
      : '')
  );
}

if (casosComBugBruto.length > 0) {
  dashboard.insights.push(
    `&#128027; ${casosComBugBruto.length} caso(s) de teste no projeto com bug aberto referenciado (issue DVAROMNIP).` +
    (casosComBugBruto.length > LIMITE_EXEMPLOS_REGRAS_TAGS
      ? ` Exibindo os primeiros ${LIMITE_EXEMPLOS_REGRAS_TAGS} na tabela abaixo.`
      : '')
  );
}

if (!auditoria.integro) {
  const naoLidos = (auditoria.arquivos_sem_conteudo || []).length;

  if (naoLidos > 0) {
    dashboard.insights.push(
      `Atenção: ${naoLidos} arquivo(s) não puderam ser lidos. O total geral está subestimado.`
    );
  }

  const definicoesPerdidas = auditoria.definicoes_perdidas || [];

  if (definicoesPerdidas.length > 0) {
    const exemplos = definicoesPerdidas
      .slice(0, 3)
      .map((d) => `${(d.caminho || '').split('/').pop()}:${d.linha}`)
      .join(', ');

    dashboard.insights.push(
      `Atenção: ${definicoesPerdidas.length} caso(s) de teste com indentação inválida (espaço/tab antes do "@") não estão sendo contabilizados e provavelmente não rodam como teste independente no Robot Framework. Ex.: ${exemplos}.`
    );
  }

  if (auditoria.commits_truncados) {
    dashboard.insights.push(
      'Atenção: a busca de commits atingiu o limite de paginação. O período pode estar incompleto.'
    );
  }

  if (auditoria.alteracoes_truncadas) {
    dashboard.insights.push(
      'Atenção: a listagem de alterações de ao menos um commit atingiu o limite de paginação.'
    );
  }
}

if (total > 0) {
  if (funcionalidades.length) {
    dashboard.insights.push(
      `A funcionalidade com maior crescimento foi "${funcionalidades[0].nome}" (${funcionalidades[0].quantidade} casos).`
    );
  }

  if (criticidades.length) {
    dashboard.insights.push(
      `${criticidades[0].quantidade} casos possuem criticidade "${criticidades[0].nome}".`
    );
  }

  if (complexidades.length) {
    dashboard.insights.push(
      `${complexidades[0].quantidade} casos possuem complexidade "${complexidades[0].nome}".`
    );
  }

  if (regressoes.length) {
    dashboard.insights.push(
      `${regressoes[0].quantidade} casos pertencem à regressão "${regressoes[0].nome}".`
    );
  }


  dashboard.insights.push(`${dashboard.indicadores.produto}% dos casos utilizam Produto.`);
  dashboard.insights.push(`${dashboard.indicadores.bd}% dos casos realizam validação em Banco de Dados.`);
  dashboard.insights.push(`${dashboard.indicadores.embalagem}% dos casos utilizam cenários de Embalagem.`);
}

return [{ json: dashboard }];

