/** Só aparece quando o total geral NÃO é confiável. */
function gerarBlocoAuditoria() {
  const semConteudo = auditoria.arquivos_sem_conteudo || [];
  const repetidos = auditoria.caminhos_repetidos || [];
  const definicoesPerdidas = auditoria.definicoes_perdidas || [];
  const commitsTruncados = auditoria.commits_truncados === true;
  const alteracoesTruncadas = auditoria.alteracoes_truncadas === true;

  if (
    semConteudo.length === 0 &&
    repetidos.length === 0 &&
    definicoesPerdidas.length === 0 &&
    !commitsTruncados &&
    !alteracoesTruncadas
  ) {
    return "";
  }

  const itens = [];

  for (const a of semConteudo) {
    itens.push(`Arquivo não lido: ${escapeHtml(a.caminho)} &mdash; ${escapeHtml(a.motivo)}`);
  }

  for (const c of repetidos) {
    itens.push(`Caminho listado mais de uma vez: ${escapeHtml(c)}`);
  }

  for (const d of definicoesPerdidas) {
    itens.push(
      `Caso de teste não contabilizado por indentação inválida em ${escapeHtml((d.caminho || '').split('/').pop())}:${d.linha} &mdash; "${escapeHtml(d.texto)}"`
    );
  }

  if (commitsTruncados) {
    itens.push("A busca de commits atingiu o limite de paginação ($top). O período pode estar incompleto.");
  }

  if (alteracoesTruncadas) {
    itens.push("A listagem de alterações de ao menos um commit atingiu o limite de paginação ($top).");
  }

  const lis = itens.map((t) => `<li style="margin-bottom:4px;">${t}</li>`).join("");

  return `
    <tr>
      <td style="padding:16px 24px 0; font-family:${FONTE};">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.vermelhoFundo}; border-left:4px solid ${CORES.vermelho}; border-radius:6px;">
          <tr>
            <td style="padding:14px 18px;">
              <div style="font-size:13px; font-weight:bold; color:${CORES.vermelho}; margin-bottom:6px;">
                &#9888; Os números deste relatório podem estar incompletos
              </div>
              <ul style="margin:0; padding-left:18px; font-size:11px; color:${CORES.cinzaTexto}; line-height:1.6;">
                ${lis}
              </ul>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  `;
}

function gerarCardsIndicadores() {
  const cards = [
    { titulo: "NOVOS CASOS NO PERÍODO", valor: resumo.total_casos ?? 0, cor: "#3b82f6" },
    {
      titulo: "TOTAL GERAL NO PROJETO",
      valor: resumo.total_geral_projeto ?? "-",
      extra: resumo.total_codigos_unicos ? `${resumo.total_codigos_unicos} código(s) único(s)` : "",
      cor: "#0ea5e9"
    },
    { titulo: "CASOS REMOVIDOS", valor: resumo.total_casos_removidos ?? 0, cor: "#dc2626" },
    {
      titulo: "CÓDIGOS DUPLICADOS",
      valor: (codigos_duplicados || []).length,
      extra: (resumo.total_duplicados ?? 0) > 0
        ? `${resumo.total_duplicados} definição(ões) excedente(s)`
        : "",
      cor: "#f59e0b"
    },
    {
      titulo: "PRINCIPAL FUNCIONALIDADE",
      valor: SEM_NOVOS ? "-" : (resumo.principal_funcionalidade ?? "-"),
      extra: !SEM_NOVOS && resumo.principal_funcionalidade_qtd
        ? `${resumo.principal_funcionalidade_qtd} caso(s)`
        : "",
      cor: "#8b5cf6"
    },
    {
      titulo: "PRINCIPAL CRITICIDADE",
      valor: SEM_NOVOS ? "-" : (resumo.principal_criticidade ?? "-"),
      cor: "#ef4444"
    }
  ];

  let linhas = "";

  for (let i = 0; i < cards.length; i += 2) {
    const par = cards.slice(i, i + 2);

    const celulas = par
      .map(
        (c) => `
        <td width="50%" style="padding:6px;" valign="top">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda};
            border-left:4px solid ${c.cor}; border-radius:6px;">
            <tr>
              <td style="padding:14px 16px; font-family:${FONTE};">
                <div style="font-size:11px; color:${CORES.textoSecundario}; letter-spacing:0.03em; margin-bottom:4px;">
                  ${escapeHtml(c.titulo)}
                </div>
                <div style="font-size:17px; font-weight:bold; color:${CORES.textoPrimario}; text-transform:capitalize;">
                  ${escapeHtml(c.valor)}
                </div>
                ${
                  c.extra
                    ? `<div style="font-size:11px; color:${CORES.textoSecundario}; margin-top:2px;">${escapeHtml(c.extra)}</div>`
                    : ""
                }
              </td>
            </tr>
          </table>
        </td>
      `
      )
      .join("");

    const preencher = par.length === 1 ? `<td width="50%" style="padding:6px;">&nbsp;</td>` : "";

    linhas += `<tr>${celulas}${preencher}</tr>`;
  }

  return `
    <tr>
      <td style="padding:20px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Indicadores Gerais
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

function gerarTabelaPorSuite() {
  if (!por_suite || por_suite.length === 0) return "";

  const cardsPasta = (total_por_pasta || [])
    .map(
      (p) => `
      <td width="50%" style="padding:6px;" valign="top">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda};
          border-left:4px solid ${CORES.primaria}; border-radius:6px;">
          <tr>
            <td style="padding:14px 16px; font-family:${FONTE};">
              <div style="font-size:11px; color:${CORES.textoSecundario}; letter-spacing:0.03em; margin-bottom:4px;">
                PASTA "${escapeHtml(p.pasta || "-")}"
              </div>
              <div style="font-size:17px; font-weight:bold; color:${CORES.textoPrimario};">
                ${p.quantidade} caso(s)
              </div>
            </td>
          </tr>
        </table>
      </td>
    `
    )
    .join("");

  const linhas = por_suite
    .map((linha, index) => {
      const bgLinha = index % 2 === 0 ? "#ffffff" : "#fafbff";
      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:7px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(linha.arquivo)}
          </td>
          <td style="padding:7px 10px; font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(linha.pasta)}
          </td>
          <td align="right" style="padding:7px 10px; font-family:${FONTE}; font-size:12px; font-weight:bold; color:${CORES.primaria}; border-bottom:1px solid ${CORES.borda};">
            ${linha.quantidade}
          </td>
        </tr>
      `;
    })
    .join("");

  const somaPorSuite = por_suite.reduce((soma, l) => soma + (l.quantidade || 0), 0);
  const unicos = resumo.total_codigos_unicos ?? somaPorSuite;

  const observacaoDivergencia =
    unicos !== somaPorSuite
      ? `<div style="font-family:${FONTE}; font-size:10px; color:${CORES.laranja}; margin-top:6px;">
           &#9888; ${somaPorSuite} definições para ${unicos} códigos únicos &mdash; detalhes na seção de duplicados.
         </div>`
      : "";

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Casos de Teste por Suíte (Total no Projeto)
        </div>

        ${
          cardsPasta
            ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-bottom:10px;"><tr>${cardsPasta}</tr></table>`
            : ""
        }

        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:#f8f9fc;">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Suíte (arquivo .robot)</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Pasta</th>
            <th align="right" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Qtd. Casos</th>
          </tr>
          ${linhas}
          <tr style="background-color:${CORES.fundoDestaque};">
            <td colspan="2" style="padding:9px 10px; font-family:${FONTE}; font-size:12px; font-weight:bold; color:${CORES.textoPrimario};">TOTAL GERAL</td>
            <td align="right" style="padding:9px 10px; font-family:${FONTE}; font-size:13px; font-weight:bold; color:${CORES.primaria};">${somaPorSuite}</td>
          </tr>
        </table>
        ${observacaoDivergencia}
      </td>
    </tr>
  `;
}

/** REQUISITO 3: duplicados com arquivo e linha. */
function gerarTabelaDuplicados() {
  if (!codigos_duplicados || codigos_duplicados.length === 0) {
    return `
      <tr>
        <td style="padding:16px 24px 0; font-family:${FONTE};">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="background-color:${CORES.verdeFundo}; border-left:4px solid ${CORES.verde}; border-radius:6px;">
            <tr>
              <td style="padding:12px 16px; font-size:12px; color:${CORES.verde}; font-weight:bold; font-family:${FONTE};">
                Nenhum código de caso de teste duplicado encontrado no repositório.
              </td>
            </tr>
          </table>
        </td>
      </tr>
    `;
  }

  const linhas = codigos_duplicados
    .map((dup, index) => {
      const bg = index % 2 === 0 ? "#fffbfb" : "#fff5f5";

      const locais = (dup.ocorrencias || [])
        .map((o) => `${escapeHtml(o.arquivo)}<span style="color:${CORES.textoSecundario};">:${o.linha}</span>`)
        .join("<br>");

      return `
        <tr style="background-color:${bg};">
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; font-weight:bold; color:${CORES.vermelho}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap; vertical-align:top;">
            ${escapeHtml(dup.codigo)}
          </td>
          <td align="center" style="padding:8px 10px; font-family:${FONTE}; font-size:12px; font-weight:bold; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; vertical-align:top;">
            ${dup.quantidade}x
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:10px; color:${CORES.cinzaTexto}; border-bottom:1px solid ${CORES.borda}; vertical-align:top;">
            ${escapeHtml(dup.tipo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; vertical-align:top; line-height:1.6;">
            ${locais}
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.vermelho}; margin-bottom:4px;">
          &#9888; Casos de Teste Duplicados (${codigos_duplicados.length} código(s))
        </div>
        <div style="font-size:11px; color:${CORES.textoSecundario}; margin-bottom:10px; line-height:1.5;">
          ${resumo.total_duplicados ?? 0} definição(ões) excedente(s). O total geral (${resumo.total_geral_projeto})
          conta ocorrências; o total de códigos únicos é ${resumo.total_codigos_unicos ?? "-"}.
          Duplicidade infla a cobertura reportada e gera execução redundante na pipeline.
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.vermelhoFundo}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:${CORES.vermelhoFundo};">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="center" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Qtd.</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Tipo</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Arquivo : linha</th>
