/**
 * Gerador genérico para as duas listas de "política de tags obrigatória":
 * casos sem "regressivo-completo" e casos sem criticidade definida.
 * Mesmo estilo visual de gerarTabelaTagsRuins, parametrizado por
 * título/cor/lista/total para não duplicar a marcação HTML duas vezes.
 * "total" pode ser maior que "lista.length" quando a exibição foi
 * cortada em "Preparar Dados para Relatório" - nesse caso mostra uma
 * nota "exibindo X de Y" em vez de fingir que a lista está completa.
 */
function gerarTabelaPoliticaTags(titulo, descricao, lista, total, cor, corFundo) {
  if (!lista || lista.length === 0) return "";

  const linhas = lista
    .map(
      (c, index) => `
      <tr style="background-color:${index % 2 === 0 ? "#ffffff" : "#fffdf5"};">
        <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; font-weight:bold; color:${cor}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap; vertical-align:top;">
          ${escapeHtml(c.codigo)}
        </td>
        <td style="padding:8px 10px; font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda}; vertical-align:top;">
          ${escapeHtml(c.caminho_arquivo)}${c.linha ? ":" + escapeHtml(c.linha) : ""}
        </td>
        <td style="padding:8px 10px; font-family:${FONTE}; font-size:10px; color:${CORES.cinzaTexto}; border-bottom:1px solid ${CORES.borda}; vertical-align:top;">
          ${c.linha_tags_bruta ? escapeHtml(c.linha_tags_bruta) : "<em>sem linha [Tags]</em>"}
        </td>
      </tr>
    `
    )
    .join("");

  const notaCorte =
    total > lista.length
      ? `<div style="font-size:10px; color:${CORES.textoSecundario}; margin-top:6px;">Exibindo ${lista.length} de ${total} caso(s). A lista completa está na varredura do projeto.</div>`
      : "";

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${cor}; margin-bottom:4px;">
          &#9888; ${escapeHtml(titulo)} (${total})
        </div>
        <div style="font-size:11px; color:${CORES.textoSecundario}; margin-bottom:10px; line-height:1.5;">
          ${descricao}
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:${corFundo};">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${cor}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${cor}; border-bottom:2px solid ${CORES.borda};">Arquivo : linha</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${cor}; border-bottom:2px solid ${CORES.borda};">Linha [Tags]</th>
          </tr>
          ${linhas}
        </table>
        ${notaCorte}
      </td>
    </tr>
  `;
}

