function gerarBlocoRanking(titulo, lista) {
  if (!lista || lista.length === 0) {
    return `<div style="font-family:${FONTE}; font-size:13px; color:${CORES.textoSecundario}; font-style:italic;">Sem dados.</div>`;
  }

  const maior = maiorQuantidade(lista);
  const ordenado = [...lista].sort((a, b) => (b.quantidade || 0) - (a.quantidade || 0));

  const linhas = ordenado
    .map((item) => {
      const percentual = ((item.quantidade || 0) / maior) * 100;
      return `
        <tr>
          <td style="padding:6px 0; font-family:${FONTE};">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td style="font-size:12px; color:${CORES.textoPrimario}; text-transform:capitalize; padding-bottom:3px;">
                  ${escapeHtml(item.nome)}
                  <span style="float:right; font-weight:bold; color:${CORES.primaria};">${escapeHtml(item.quantidade)}</span>
                </td>
              </tr>
              <tr>
                <td>${gerarBarra(percentual, CORES.primaria, "#eef0f5", 7)}</td>
              </tr>
            </table>
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
      <tr><td style="font-family:${FONTE}; font-size:13px; font-weight:bold; color:${CORES.textoPrimario}; padding-bottom:8px;">${escapeHtml(titulo)}</td></tr>
      ${linhas}
    </table>
  `;
}

function gerarSecaoRankings() {
  // Sem casos novos, os rankings viram quatro caixas vazias. Suprime.
  if (SEM_NOVOS) return "";

  const blocos = [
    gerarBlocoRanking("Por Funcionalidade", rankings.funcionalidades),
    gerarBlocoRanking("Por Criticidade", rankings.criticidades),
    gerarBlocoRanking("Por Regressão", rankings.regressoes),
    gerarBlocoRanking("Por Complexidade", rankings.complexidades)
  ];

  let linhas = "";

  for (let i = 0; i < blocos.length; i += 2) {
    const par = blocos.slice(i, i + 2);
    linhas += `
      <tr>
        <td width="50%" valign="top" style="padding:10px; background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          ${par[0]}
        </td>
        <td width="12"></td>
        <td width="50%" valign="top" style="padding:10px; background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          ${par[1] || "&nbsp;"}
        </td>
      </tr>
      <tr><td colspan="3" height="12"></td></tr>
    `;
  }

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Rankings (novos casos do período)
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

function gerarIndicadoresTecnicos() {
  // Sem casos novos, todo indicador é 0% -> barra vermelha enganosa. Suprime.
  if (SEM_NOVOS) return "";

  const chaves = Object.keys(indicadores);
  if (chaves.length === 0) return "";

  const linhas = chaves
    .sort((a, b) => (indicadores[b] || 0) - (indicadores[a] || 0))
    .map((chave) => {
      const percentual = indicadores[chave] ?? 0;
      const qtd = recursos[chave] ?? "-";
      const corBarra = percentual >= 80 ? CORES.verde : percentual >= 50 ? CORES.laranja : CORES.vermelho;

      return `
        <tr>
          <td style="padding:8px 0; font-family:${FONTE};">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              <tr>
                <td style="font-size:12px; color:${CORES.textoPrimario}; text-transform:capitalize; padding-bottom:3px;">
                  ${escapeHtml(chave.replace(/_/g, " "))}
                  <span style="float:right; color:${CORES.textoSecundario};">
                    <b style="color:${CORES.textoPrimario};">${percentual}%</b> (${escapeHtml(qtd)} casos)
                  </span>
                </td>
              </tr>
              <tr>
                <td>${gerarBarra(percentual, corBarra, "#eef0f5", 8)}</td>
              </tr>
            </table>
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Indicadores Técnicos (novos casos do período)
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px;">
          <tr><td style="padding:14px 16px;">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
              ${linhas}
            </table>
          </td></tr>
        </table>
      </td>
    </tr>
  `;
}

function gerarInsights() {
  if (!insights || insights.length === 0) return "";

  const linhas = insights
    .map(
      (texto) => `
      <tr>
        <td style="padding-bottom:8px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
            style="background-color:${CORES.fundoDestaque}; border-left:3px solid ${CORES.primaria}; border-radius:4px;">
            <tr>
              <td style="padding:10px 14px; font-family:${FONTE}; font-size:13px; color:${CORES.textoPrimario};">
                ${escapeHtml(texto)}
              </td>
            </tr>
          </table>
        </td>
      </tr>
    `
    )
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 8px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Insights Executivos
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          ${linhas}
        </table>
      </td>
    </tr>
  `;
}

function gerarTabelaCasos() {
  if (!casos || casos.length === 0) return "";

  const linhas = casos
    .map((caso, index) => {
      const bgLinha = index % 2 === 0 ? "#ffffff" : "#fafbff";
      const critStyle = estiloCriticidade(caso.criticidade);
      const compStyle = estiloComplexidade(caso.complexidade);
      const regressoes = Array.isArray(caso.regressao) ? caso.regressao.join(", ") : caso.regressao || "-";

      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.primaria}; font-weight:bold; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.codigo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(caso.descricao)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.funcionalidade)}
          </td>
          <td style="padding:8px 10px; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${gerarBadge(caso.criticidade, critStyle.cor, critStyle.fundo)}
          </td>
          <td style="padding:8px 10px; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${gerarBadge(caso.complexidade, compStyle.cor, compStyle.fundo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(regressoes)}
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 24px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.textoPrimario}; margin-bottom:10px;">
          Tabela Completa de Casos (${casos.length})
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.borda}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:#f8f9fc;">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Descrição</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Funcionalidade</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Criticidade</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Complexidade</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.textoSecundario}; border-bottom:2px solid ${CORES.borda};">Regressão</th>
          </tr>
          ${linhas}
        </table>
        <div style="font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; margin-top:6px;">
          * Coluna "Caminho do Arquivo" omitida nesta versão para melhor leitura no e-mail.
        </div>
      </td>
    </tr>
  `;
}

function gerarTabelaCasosRemovidos() {
  if (!casos_removidos || casos_removidos.length === 0) return "";

  const linhas = casos_removidos
    .map((caso, index) => {
      const bgLinha = index % 2 === 0 ? "#fffbfb" : "#fff5f5";

      return `
        <tr style="background-color:${bgLinha};">
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.vermelho}; font-weight:bold; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.codigo)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda}; text-decoration:line-through;">
            ${escapeHtml(caso.descricao)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:11px; color:${CORES.textoPrimario}; border-bottom:1px solid ${CORES.borda}; white-space:nowrap;">
            ${escapeHtml(caso.funcionalidade)}
          </td>
          <td style="padding:8px 10px; font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; border-bottom:1px solid ${CORES.borda};">
            ${escapeHtml(caso.caminho_arquivo)}
          </td>
        </tr>
      `;
    })
    .join("");

  return `
    <tr>
      <td style="padding:16px 24px 24px; font-family:${FONTE};">
        <div style="font-size:16px; font-weight:bold; color:${CORES.vermelho}; margin-bottom:10px;">
          &#9888; Casos Removidos do Repositório (${casos_removidos.length})
        </div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
          style="background-color:${CORES.fundoCard}; border:1px solid ${CORES.vermelhoFundo}; border-radius:6px; overflow:hidden;">
          <tr style="background-color:${CORES.vermelhoFundo};">
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Código</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Descrição</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Funcionalidade</th>
            <th align="left" style="padding:9px 10px; font-family:${FONTE}; font-size:10px; text-transform:uppercase; color:${CORES.vermelho}; border-bottom:2px solid ${CORES.borda};">Arquivo</th>
          </tr>
          ${linhas}
        </table>
        <div style="font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; margin-top:6px;">
          * Casos que existiam no início do período e não foram mais encontrados no repositório. Avalie se devem ser retirados formalmente do plano de testes.
        </div>
      </td>
    </tr>
  `;
}

function gerarRodape() {
  const conf = auditoria.conferencia || {};

  const linhaConferencia =
    conf.resultado_esperado_vscode !== undefined
      ? `<div style="font-family:${FONTE}; font-size:10px; color:${CORES.textoSecundario}; text-align:center; margin-top:4px;">
           Conferência: ${conf.definicoes} definições em ${auditoria.arquivos_lidos} arquivo(s).
           Busca literal "@${escapeHtml((resumo.prefixo_caso || "GTPDV-T"))}" no editor deve retornar ${conf.resultado_esperado_vscode}.
         </div>`
      : "";

  if (!linhaConferencia) return "";

  return `
    <tr>
      <td style="padding:8px 24px 20px;">
        ${linhaConferencia}
      </td>
    </tr>
  `;
}

