function montarEmailCompleto() {
  // Cada seção fica em uma variável antes de montar o HTML final -
  // deixa mais simples inserir/reordenar blocos e mantém o padrão já
  // usado no resto do arquivo.
  const secoes = {
    cabecalho: gerarCabecalho(),
    avisoSemNovos: gerarAvisoSemNovosCasos(),
    blocoAuditoria: gerarBlocoAuditoria(),
    cardsIndicadores: gerarCardsIndicadores(),
    tabelaPorSuite: gerarTabelaPorSuite(),
    tabelaDuplicados: gerarTabelaDuplicados(),
    tabelaTagsRuins: gerarTabelaTagsRuins(),
    tabelaSemRegressivoCompleto: gerarTabelaSemRegressivoCompleto(),
    tabelaSemCriticidade: gerarTabelaSemCriticidade(),
    tabelaCasosComBug: gerarTabelaCasosComBug(),
    secaoRankings: gerarSecaoRankings(),
    indicadoresTecnicos: gerarIndicadoresTecnicos(),
    insightsSecao: gerarInsights(),
    tabelaCasos: gerarTabelaCasos(),
    tabelaCasosRemovidos: gerarTabelaCasosRemovidos(),
    rodape: gerarRodape()
  };

  return `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Relatório de Casos de Teste</title>
</head>
<body style="margin:0; padding:0; background-color:${CORES.fundoPagina};">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:${CORES.fundoPagina};">
    <tr>
      <td align="center" style="padding:24px 12px;">
        <table role="presentation" width="${LARGURA_TOTAL}" cellpadding="0" cellspacing="0" border="0"
          style="max-width:${LARGURA_TOTAL}px; width:100%; background-color:${CORES.fundoCard}; border-radius:8px; overflow:hidden;">
          ${secoes.cabecalho}
          ${secoes.avisoSemNovos}
          ${secoes.blocoAuditoria}
          ${secoes.cardsIndicadores}
          ${secoes.tabelaPorSuite}
          ${secoes.tabelaDuplicados}
          ${secoes.tabelaTagsRuins}
          ${secoes.tabelaSemRegressivoCompleto}
          ${secoes.tabelaSemCriticidade}
          ${secoes.tabelaCasosComBug}
          ${secoes.secaoRankings}
          ${secoes.indicadoresTecnicos}
          ${secoes.insightsSecao}
          ${secoes.tabelaCasos}
          ${secoes.tabelaCasosRemovidos}
          ${secoes.rodape}
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
  `.trim();
}

const htmlFinal = montarEmailCompleto();

return [
  {
    json: {
      html: htmlFinal,
      periodo_criacao_inicio,
      periodo_criacao_fim,
      total_casos: resumo.total_casos ?? casos.length,
      total_casos_removidos: resumo.total_casos_removidos ?? casos_removidos.length,
      total_geral_projeto: resumo.total_geral_projeto ?? null,
      total_duplicados: resumo.total_duplicados ?? 0,
      sem_novos_casos: SEM_NOVOS,
      auditoria_integro: auditoria.integro !== false
    }
  }
];
